<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {useRoute} from 'vue-router';import {runs} from '../stores/runs';import {draws} from '../stores/draws';import PageHeading from '../components/common/PageHeading.vue';import StatusPill from '../components/common/StatusPill.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import AllocationTable from '../components/AllocationTable.vue';import QuotaBars from '../components/QuotaBars.vue';const route=useRoute(),selected=ref(String(route.query.run||'demo-run'));watch(()=>route.query.run,value=>{selected.value=String(value||'demo-run')});let timer:ReturnType<typeof setInterval>;onMounted(()=>{runs.load();draws.load();timer=setInterval(()=>{runs.load();draws.load()},2000)});onUnmounted(()=>clearInterval(timer));const run=computed(()=>runs.items.value.find(r=>r.id===selected.value)),result=computed(()=>run.value?.result),draw=computed(()=>draws.items.value.find(r=>r.run_id===selected.value))</script><template><PageHeading index="03 / 预算分层" title="每一份配额，都能还原到假设。" note="超几何模型精确计算无放回漏检率；整数配额满足最低需求、层容量与总预算。预算不够不会生成抽样。"/><div class="result-toolbar"><label>运行记录<select v-model="selected"><option v-for="r in runs.items.value" :key="r.id" :value="r.id">{{r.id==='demo-run'?'四层基线':r.id.slice(0,8)}} · {{r.status}}</option></select></label><StatusPill v-if="run" :status="run.status"/></div><Notice :message="runs.error.value"/><Notice v-if="run?.status==='failed'" :message="run.error"/><EmptyState v-if="run&&['queued','running'].includes(run.status)" text="后台正在求最小样本量、Neyman整数配额和具体文档样本，每两秒刷新。"/><div v-if="result&&['completed','infeasible'].includes(run?.status||'')" class="allocation-layout"><section><div class="budget-line"><div><small>给定预算</small><strong>{{result.budget}}</strong></div><div><small>最低需求</small><strong>{{result.required_budget??'不可达'}}</strong></div><div><small>总体容量</small><strong>{{result.capacity}}</strong></div></div><Notice v-if="!result.feasible" :message="result.reason"/><AllocationTable :rows="result.strata"/><p class="method-note">{{result.assumption}}</p><router-link v-if="draw" :to="'/draws?draw='+draw.id" class="action-link">打开 {{draw.manifest.length}} 份具体文档清单 →</router-link><p v-if="result.feasible&&!draw" class="method-note">配额已完成，正在保存抽样清单…</p></section><aside class="margin-note"><p class="eyebrow">ALLOCATION BASIS</p><h2>配额如何分配</h2><QuotaBars :rows="result.strata"/><p>权重=N×√(p×(1−p))，p为层内按文档量加权预估差错率。带最低样本与容量约束求连续配额，再按最大余数整数化。</p><p>正方差层满额后仍有预算，零方差层按固定顺序分配剩余额度。seed={{result.seed}}。</p></aside></div></template>
